(function(g){function sim(nodes){let a=1,dec=.03,min=.001,forces=[],ticks=[],run=true;function step(){if(!run)return;a=a*(1-dec);forces.forEach(f=>f(a));nodes.forEach(n=>{n.vx=(n.vx||0)*.85;n.vy=(n.vy||0)*.85;n.x+=n.vx||0;n.y+=n.vy||0});ticks.forEach(h=>h());if(a<min){run=false;return}requestAnimationFrame(step)}requestAnimationFrame(step);return{nodes:()=>nodes,force:(name,f)=>{if(f){f.nodes=nodes;forces.push(f)}return this},on:(e,h)=>{if(e==='tick')ticks.push(h);return this},restart:()=>{run=true;a=1;requestAnimationFrame(step);return this}}}
function forceCenter(cx,cy){return function(alpha){(this.nodes||[]).forEach(n=>{n.vx=(n.vx||0)+(cx-n.x)*.0015*alpha;n.vy=(n.vy||0)+(cy-n.y)*.0015*alpha})}}
function forceManyBody(s){s=s||-60;return function(alpha){const nodes=this.nodes||[];for(let i=0;i<nodes.length;i++){for(let j=i+1;j<nodes.length;j++){const a=nodes[i],b=nodes[j];let dx=a.x-b.x,dy=a.y-b.y;let d=Math.sqrt(dx*dx+dy*dy)||.01;let k=(s/d)*.002*alpha;a.vx=(a.vx||0)+dx*k;a.vy=(a.vy||0)+dy*k;b.vx=(b.vx||0)-dx*k;b.vy=(b.vy||0)-dy*k}}}}
function forceLink(links,dist){dist=dist||80;return function(alpha){const by=new Map((this.nodes||[]).map(n=>[n.id,n]));(links||[]).forEach(l=>{const s=by.get(l.source)||l.source;const t=by.get(l.target)||l.target;if(!s||!t)return;let dx=t.x-s.x,dy=t.y-s.y;let d=Math.sqrt(dx*dx+dy*dy)||.01;let diff=(d-dist)/d;let k=.05*alpha;let mx=dx*diff*k,my=dy*diff*k;s.vx=(s.vx||0)+mx;s.vy=(s.vy||0)+my;t.vx=(t.vx||0)-mx;t.vy=(t.vy||0)-my})}}
function drag(svg,nodes,onMove){let dragging=null;function pointer(evt){const pt=svg.createSVGPoint();pt.x=evt.clientX;pt.y=evt.clientY;const p=pt.matrixTransform(svg.getScreenCTM().inverse());return{x:p.x,y:p.y}}svg.addEventListener('pointerdown',e=>{const t=e.target.closest('[data-node]');if(!t)return;const id=t.getAttribute('data-node');dragging=nodes.find(n=>n.id===id);if(dragging){svg.setPointerCapture(e.pointerId);const p=pointer(e);dragging.x=p.x;dragging.y=p.y;dragging.vx=0;dragging.vy=0;onMove&&onMove()}});svg.addEventListener('pointermove',e=>{if(!dragging)return;const p=pointer(e);dragging.x=p.x;dragging.y=p.y;dragging.vx=0;dragging.vy=0;onMove&&onMove()});svg.addEventListener('pointerup',()=>{dragging=null})}

g.d3={forceSimulation:sim,forceCenter,forceManyBody,forceLink,drag};})(window);
